import {beginAction,endAction,notify,noteRequest} from './action-feedback.js?v=1';
import {captureFormDrafts,restoreFormDrafts} from './ui-continuity.js?v=3';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let h,key='',data,detail,error='',busy=false,loading=false,page=0,filter='active';
let changeView='list',changeStatus='PENDING',changeDecision=null;const CHANGE_PAGE_SIZE=10;
let badge=null,watchPage=0,pendingSnooze=null;const expanded=new Set();
// Opened from the reviewer overview with a filter, a tab or one proposal.
let pendingChanges=null;export function openChanges(options={}){pendingChanges=options;key='';}
export const alertUnreadCount=()=>badge&&badge.companyId===h?.company()?.id?badge.count:0;
export async function refreshAlertBadge(){const id=h?.company()?.id;if(!id)return;const counts=await h.api(`/companies/${id}/alerts?countOnly=true`);badge={companyId:id,count:counts.unread};}
const labels={NEW:'Chờ phân loại',OBLIGATION_UPDATE:'Đang sửa nghĩa vụ',NEEDS_IMPORT:'Cần nhập văn bản',PENDING:'Chờ chuyên gia',APPROVED:'Đã duyệt',REJECTED:'Đã loại',TEXT:'Toàn văn thay đổi',METADATA:'Thông tin văn bản thay đổi',RELATION:'Có quan hệ sửa đổi cần xác minh',NEW_DOCUMENT:'Văn bản mới',PARSER_CHANGE:'Thay đổi bộ phân tích',MANUAL:'Đề xuất của chuyên gia',ATTACHMENT:'File gốc thay đổi',LAW_CHANGE:'Thay đổi pháp luật',VERIFY_SCOPE:'Cần xác minh phạm vi',REMINDER:'Nhắc hạn'};
const btn=(label,action,id='')=>`<button type="button" class="secondary-button" data-alert-action="${action}" data-id="${esc(id)}" ${busy?'disabled':''}>${label}</button>`;
const field=(name,label,type='text',value='',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`;
const area=(name,label,value='')=>`<label>${label}<textarea name="${name}" rows="4" minlength="10" required>${esc(value)}</textarea></label>`;
const date=x=>x?new Date(x).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}):'Chưa có';
const changeFields={releaseId:'bộ checklist',effectiveDate:'ngày áp dụng',versionIds:'checklist liên quan',whatChanged:'thay đổi điều gì',why:'vì sao doanh nghiệp cần chú ý',action:'doanh nghiệp cần làm gì',note:'kết quả xác minh nguồn',sourceVerified:'xác nhận đối chiếu nguồn',title:'tên thay đổi',sourceUrl:'URL văn bản'};
const invalidChange=e=>e.code==='INVALID_REQUEST'?(e.fields?.length?'Kiểm tra '+[...new Set(e.fields.map(x=>changeFields[x]||x))].join(', ')+'. Mỗi phần diễn giải và ghi chú cần ít nhất 10 ký tự.':'Kiểm tra bộ checklist, ngày áp dụng, checklist liên quan và các phần diễn giải (ít nhất 10 ký tự).'):null;
function checkText(f,name,label){if(String(f.get(name)||'').trim().length<10)throw Error(`${label} cần ít nhất 10 ký tự.`);}
export function configureAlerts(hooks){h=hooks;}
export function invalidateAlerts(){key='';data=null;detail=null;badge=null;pendingSnooze=null;expanded.clear();}
async function run(fn){if(busy)return;const formDrafts=captureFormDrafts();busy=true;error='';h.render();restoreFormDrafts(formDrafts);const action=beginAction();try{await fn();endAction(action);}catch(e){error=invalidChange(e)||({INVALID_EFFECTIVE_DATE:'Ngày áp dụng phải nằm trong hiệu lực của các nghĩa vụ đã chọn.',RELEASE_AFTER_EFFECTIVE_DATE:'Bộ checklist phải được phát hành trước ngày đánh giá áp dụng.',INVALID_IMPACT_VERSIONS:'Chọn nghĩa vụ đã duyệt trong đúng bộ phát hành.',SELECT_OBLIGATIONS:'Chọn ít nhất một nghĩa vụ cần sửa.',PUBLISHED_ONLY:'Chỉ chọn nghĩa vụ đang được phát hành.',REVISION_CONFLICT:'Đề xuất đã được xử lý ở phiên khác. Hãy tải lại.',PARSER_CHANGE_NOT_LEGAL:'Thay đổi parser cần kiểm tra kỹ thuật; không được duyệt thành luật thay đổi.',SOURCE_NOT_ALLOWED:'Chỉ nhận URL nguồn chính thức đã cho phép.',INVALID_SNOOZE:'Chọn ngày nhắc lại trong 90 ngày tới.'}[e.code])||e.message;}finally{busy=false;h.render();if(error){restoreFormDrafts(formDrafts);notify(error,'error');}}}
async function refresh(){if(h.screen()==='changes'){const [c,w,r]=await Promise.all([h.api('/admin/changes?page='+page+'&pageSize='+CHANGE_PAGE_SIZE+(changeStatus==='all'?'':['OBLIGATION_UPDATE','NEEDS_IMPORT'].includes(changeStatus)?'&stage='+changeStatus:'&status='+changeStatus)),h.api('/admin/watchset?page='+watchPage),h.api('/admin/releases')]);if(page>0&&page*CHANGE_PAGE_SIZE>=c.total){page=Math.max(0,Math.ceil(c.total/CHANGE_PAGE_SIZE)-1);return refresh();}data={...c,watch:w,releases:r.items};}else{const id=h.company().id;data=await h.api(`/companies/${id}/alerts?page=${page}`);badge={companyId:id,count:data.unread};}}
export function mountAlerts(){if(h&&!['alerts','changes'].includes(h.screen())){key='';pendingSnooze=null;return;}if(busy||!h||!['alerts','changes'].includes(h.screen())||!h.account()||h.screen()==='alerts'&&!h.company())return;const next=[h.screen(),h.account().user.id,h.company()?.id].join(':');if(key!==next){key=next;data=null;detail=null;page=0;const open=h.screen()==='changes'?pendingChanges:null;pendingChanges=null;if(h.screen()==='changes'){changeStatus=open?.status||'PENDING';changeView=open?.view||'list';changeDecision=null;}loading=true;void run(async()=>{try{await refresh();if(open?.id){detail=await h.api('/admin/changes/'+open.id);changeDecision=detail.workflow?.ready?'notify':null;}}finally{loading=false;}});}}
const cite=c=>`<details><summary>Điều khoản làm căn cứ</summary><a target="_blank" rel="noopener" href="/workspace?view=laws&law=${esc(c.documentId)}&snapshotId=${esc(c.snapshotId)}&parseRunId=${esc(c.parseRunId)}&provision=${esc(c.provisionId)}">Mở đúng phiên bản trong thư viện</a><p class="compliance-quote">${esc(c.quote)}</p></details>`;
export function renderAlertsProduct(kind='alerts'){
 if(!h?.account())return '';if(kind==='changes'&&!h.account().user.platformReviewer)return '<p>Chỉ chuyên gia được cấp quyền mới xem phòng duyệt.</p>';if(kind==='alerts'&&!h.company())return '<p>Chọn doanh nghiệp trước khi xem cảnh báo.</p>';
 const top=`<section class="form-panel product-panel compliance-panel"><h1>${kind==='changes'?'Theo dõi và duyệt thay đổi luật':'Cảnh báo doanh nghiệp'}</h1>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="panel-actions">${btn('Tải lại','refresh')}${detail?btn('Quay lại','back'):''}${kind==='changes'?'<button class="secondary-button" data-nav="admin">Duyệt checklist</button>':''}</div>`;
 if(loading||!data||key!==[h.screen(),h.account().user.id,h.company()?.id].join(':'))return top+'<p role="status">Đang tải từ máy chủ…</p></section>';
 if(kind==='changes')return top+(detail?renderChange(detail):renderChanges())+'</section>';
 const setting=data.reminderSetting,items=data.items.filter(x=>filter==='all'||!x.userState?.snoozedUntil||new Date(x.userState.snoozedUntil)<=new Date());
 return top+`<p>Cảnh báo chỉ đến từ công việc thật hoặc thay đổi luật đã được chuyên gia duyệt. Trạng thái đọc và tạm ẩn lưu riêng theo tài khoản.</p>${h.canEdit()?`<details class="reviewer-aux"><summary>Cài đặt nhắc hạn</summary><form id="alert-settings" class="product-form"><h2>Nhắc hạn</h2><label><input name="enabled" type="checkbox" ${setting.enabled?'checked':''}> Bật nhắc hạn trong web</label>${field('preparationDays','Nhắc chuẩn bị trước hạn bao nhiêu ngày','number',setting.preparationDays)}<p>Giờ Việt Nam. Nhắc trước hạn, đúng ngày và quá hạn; ngày chuẩn bị không thay thế hạn pháp lý. Chưa gửi email/SMS.</p><button class="primary-button" ${busy?'disabled':''}>Lưu cấu hình nhắc hạn</button></form></details>`:''}<div class="panel-actions">${btn(filter==='active'?'Hiện cả mục tạm ẩn':'Ẩn mục đã tạm ẩn','filter')}</div>${items.map(renderAlert).join('')||'<div class="info-callout">Chưa có cảnh báo trong trang này. Thay đổi đang chờ duyệt sẽ chưa gửi tới doanh nghiệp.</div>'}${pagination(data.total)}</section>`;
}
function renderAlert(a){const p=a.payloadJson,s=a.userState;return `<article class="alert-live-card alert-card real-alert"><h2>${esc(a.title)}</h2><p>${labels[a.kind]} · ${date(a.createdAt)} · ${s?.readAt?'Đã đọc':'Chưa đọc'}${s?.snoozedUntil?' · Tạm ẩn đến '+date(s.snoozedUntil):''}</p>${expanded.has(a.id)?`<div class="alert-detail">${a.kind==='REMINDER'?`<p>${esc(p.explanation)}</p><p>Hạn pháp lý: ${esc(p.legalDeadline||'Chưa xác định')} · Ngày tự đặt: ${esc(p.userDeadline||'Chưa đặt')} · Ngày nhắc: ${esc(p.reminderDate)}</p>`:`<p><strong>Thay đổi:</strong> ${esc(p.whatChanged)}</p><p><strong>Vì sao liên quan:</strong> ${esc(p.why)} ${esc(p.explanation)}</p><p><strong>Ngày áp dụng:</strong> ${esc(p.effectiveDate)}</p>${a.kind==='VERIFY_SCOPE'?`<div class="info-callout">Cần bổ sung: ${esc(p.missingFacts.map(x=>({channels:'Kênh bán hàng',employeeCount:'Số lao động',activity:'Hoạt động',places:'Loại cơ sở','site.kind':'Loại địa điểm','site.province':'Tỉnh của địa điểm',signals:'Tình huống phát sinh'}[x]||x)).join(', '))}. Chưa kết luận nghĩa vụ áp dụng.</div>`:''}<p>Bộ checklist ${esc(p.releaseName||'đã phát hành')} · hồ sơ phiên bản ${esc(p.profileVersion||'đã lưu')}</p>${p.completedTaskPreserved?'<div class="info-callout">Công việc đã hoàn thành giữ nguyên căn cứ cũ. Xem và xác nhận thay đổi căn cứ khi cần.</div>':''}${(p.citations||[]).map(cite).join('')}`}<p><strong>Việc cần làm:</strong> ${esc(p.action)}</p></div>`:`<p class="alert-card-summary">${esc(p.whatChanged||p.explanation||p.action||'Mở chi tiết để đối chiếu tác động và căn cứ.')}</p>`}<button type="button" class="alert-expand" data-alert-action="expand" data-id="${esc(a.id)}" aria-expanded="${expanded.has(a.id)}">${expanded.has(a.id)?'Thu gọn':'Xem tác động, lộ trình và căn cứ'} ${h.icon('chevron',15)}</button><div class="panel-actions">${btn(s?.readAt?'Đánh dấu chưa đọc':'Đã đọc','read',a.id)}${btn(s?.snoozedUntil?'Bỏ tạm ẩn':'Chọn ngày nhắc lại','snooze',a.id)}${h.canEdit()&&a.decisionId?btn('Mở / tạo công việc','task',a.id):''}<button class="secondary-button" data-nav="profile">Bổ sung hồ sơ</button></div></article>`;}
function pagination(total){return `<div class="panel-actions">${page>0?btn('Trang trước','previous'):''}<span>Trang ${page+1}</span>${(page+1)*50<total?btn('Trang sau','next'):''}</div>`;}
function collectionTime(c){const collected=c.collectedAt||c.observation?.observedAt;return `<p class="field-hint">${collected?`Thu thập lúc: <time datetime="${esc(collected)}">${esc(date(collected))}</time> (giờ Việt Nam)`:c.kind==='MANUAL'?`Tạo đề xuất lúc: <time datetime="${esc(c.createdAt)}">${esc(date(c.createdAt))}</time> (giờ Việt Nam)`:'Chưa ghi nhận ngày giờ thu thập'}</p>`;}
function changePagination(){const pages=Math.max(1,Math.ceil(data.total/CHANGE_PAGE_SIZE)),first=data.total?page*CHANGE_PAGE_SIZE+1:0,last=Math.min((page+1)*CHANGE_PAGE_SIZE,data.total);const numbers=[...new Set([0,pages-1,page-1,page,page+1])].filter(n=>n>=0&&n<pages).sort((a,b)=>a-b);
 return `<nav class="change-pagination" aria-label="Trang đề xuất"><span>${first}–${last} / ${data.total} đề xuất · Trang ${page+1}/${pages}</span><div><button type="button" class="secondary-button" data-alert-action="change-page" data-id="${page-1}" ${busy||page===0?'disabled':''}>Trước</button>${numbers.map((n,i)=>`${i&&n>numbers[i-1]+1?'<span class="page-gap">…</span>':''}<button type="button" class="change-page-number" data-alert-action="change-page" data-id="${n}" ${n===page?'aria-current="page"':''} ${busy?'disabled':''}>${n+1}</button>`).join('')}<button type="button" class="secondary-button" data-alert-action="change-page" data-id="${page+1}" ${busy||page+1>=pages?'disabled':''}>Sau</button></div></nav>`;}
function renderChanges(){const tabs=`<nav class="change-tabs" aria-label="Quản lý thay đổi luật">${[['list','Danh sách đề xuất'],['manual','Tạo đề xuất'],['sources','Nguồn đã lưu']].map(([id,label])=>`<button type="button" data-alert-action="change-view" data-id="${id}" ${changeView===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`;
 if(changeView==='manual')return tabs+`<form id="change-manual" class="product-form"><h2>Đề xuất thay đổi từ nguồn chuyên gia kiểm tra</h2>${field('title','Tên thay đổi')}${field('sourceUrl','URL văn bản chính thức','url')}${area('note','Nội dung cần xác minh')}<button class="primary-button" ${busy?'disabled':''}>Lưu đề xuất chờ duyệt</button></form>`;
 if(changeView==='sources')return tabs+`<p class="info-callout">Tự crawl đang tạm dừng. Các nguồn và dữ liệu đã thu thập được giữ để đối chiếu.</p><h2>Nguồn đã lưu (${data.watch.total})</h2><p>${data.watch.pendingImpacts} doanh nghiệp đang chờ đánh giá · ${data.watch.failedImpacts} lượt đánh giá cần xử lý.</p>${(data.watch.failedImpactItems||[]).map(x=>`<div class="product-row"><span>Đánh giá thay đổi chưa thành công · ${esc(x.errorCode)} · ${x.attempts} lần thử</span>${btn('Thử lại đánh giá','impact-retry',x.id)}</div>`).join('')}${data.watch.domains.map(d=>`<p><strong>${esc(d.domain)}</strong> · Thành công gần nhất: ${date(d.lastSuccessAt)} · ${esc(d.lastError||'Không có lỗi ghi nhận')}</p>`).join('')}${data.watch.items.map(w=>`<div class="product-row"><div><a target="_blank" rel="noopener" href="${esc(w.url)}">${esc(w.url)}</a><p>${esc(w.mode)} · ${w.enabled?'Đang theo dõi':'Tạm dừng'} · Thành công: ${date(w.lastSuccessAt)} · ${esc(w.lastError||'')}</p></div><div></div></div>`).join('')}<div class="panel-actions">${watchPage>0?btn('Nguồn trước','watch-previous'):''}<span>Trang nguồn ${watchPage+1}</span>${(watchPage+1)*50<data.watch.total?btn('Nguồn tiếp','watch-next'):''}</div>`;
 return tabs+`<div class="change-list-heading"><div><h2>Đề xuất thay đổi luật <span>${data.total}</span></h2><p>Đối chiếu nguồn và checklist liên quan. Duyệt xong, cảnh báo tự đến doanh nghiệp phù hợp.</p></div></div><div class="change-status-filters" role="group" aria-label="Lọc trạng thái đề xuất">${[['PENDING','Chờ duyệt'],['OBLIGATION_UPDATE','Đang sửa nghĩa vụ'],['NEEDS_IMPORT','Cần nhập văn bản'],['APPROVED','Đã duyệt'],['REJECTED','Đã loại'],['all','Tất cả']].map(([id,label])=>`<button type="button" data-alert-action="change-status" data-id="${id}" aria-pressed="${changeStatus===id}" ${busy?'disabled':''}>${label}<span>${data.counts?.[id]??(changeStatus===id?data.total:'—')}</span></button>`).join('')}</div><p class="change-filter-summary" role="status">Đang xem: <strong>${({all:'Tất cả đề xuất',PENDING:'Chờ duyệt',OBLIGATION_UPDATE:'Đang sửa nghĩa vụ',NEEDS_IMPORT:'Cần nhập văn bản',APPROVED:'Đã duyệt',REJECTED:'Đã loại'})[changeStatus]}</strong> · ${data.total} đề xuất${data.counts?' / '+data.counts.all+' tổng cộng':''}</p>${bulkBar()}<div class="change-review-list">${data.items.map(c=>`<article class="product-row change-review-card"><div class="change-review-main"><div class="change-review-meta">${c.status==='PENDING'?`<input type="checkbox" name="bulk" value="${esc(c.id)}" form="change-bulk-reject" aria-label="Chọn đề xuất để loại hàng loạt">`:''}<span class="status-badge ${c.status==='APPROVED'?'teal':c.status==='PENDING'?'amber':''}">${labels[c.status]}</span><span>${labels[c.kind]||esc(c.kind)}</span>${c.status==='PENDING'&&c.stage&&c.stage!=='NEW'?`<span class="status-badge blue">${labels[c.stage]}</span>`:''}${c.impact?.length?`<span class="change-impact-badge" title="${esc(c.impact.map(x=>x.title).join('; '))}">Liên quan ${c.impact.length} nghĩa vụ</span>`:''}</div><h3>${esc(c.title)}</h3>${collectionTime(c)}</div>${btn('Xem đối chiếu','change',c.id)}</article>`).join('')||'<div class="empty-state"><h3>Không có đề xuất trong mục này</h3><p>Chọn trạng thái khác để xem các đề xuất đã lưu.</p></div>'}</div>${changePagination()}`;
}
// Bốn quyết định thay cho Duyệt/Loại. Gợi ý (nghĩa vụ liên quan, nội dung soạn sẵn) chỉ dựa trên số hiệu và metadata đã thu thập.
const REJECT_REASONS=['Không tạo nghĩa vụ cho doanh nghiệp (chỉ đạo, điều hành nội bộ của cơ quan nhà nước).','Văn bản cá biệt, không áp dụng chung cho doanh nghiệp.','Ngoài lĩnh vực đang theo dõi trong bộ checklist.','Văn bản hợp nhất, không thay đổi nội dung quy định.','Trùng với đề xuất khác đã xử lý.','Lỗi thu thập dữ liệu, không phải thay đổi pháp lý.'];
const DECISIONS=[['notify','Chỉ thông báo cho doanh nghiệp','Nghĩa vụ hiện tại vẫn đúng; gửi cảnh báo để doanh nghiệp rà soát.'],['update','Cần sửa nghĩa vụ','Tạo bản nháp mới cho nghĩa vụ bị ảnh hưởng; gửi cảnh báo sau khi phát hành lại.'],['new','Nghĩa vụ mới','Văn bản tạo nghĩa vụ chưa có trong checklist; cần nhập văn bản vào kho để soạn.'],['reject','Không liên quan','Loại đề xuất với lý do có sẵn.']];
const draftStatusText={DRAFT:'bản nháp chờ sửa',IN_REVIEW:'đang chờ duyệt',PUBLISHED:'đã duyệt, chờ phát hành bộ checklist',RETIRED:'đã ngừng'};
const reasonSelect=()=>`<label>Lý do<select name="reason" required><option value="">Chọn lý do</option>${REJECT_REASONS.map(r=>`<option>${esc(r)}</option>`).join('')}</select></label>`;
const releaseChecks=selected=>data.releases[0].items.map(i=>`<label class="compliance-check"><input type="checkbox" name="versionIds" value="${i.versionId}" ${selected.includes(i.versionId)?'checked':''}>${esc(i.version?.contentJson?.title||i.versionId)}</label>`).join('');
function rejectNote(f){const reason=String(f.get('reason')||''),extra=String(f.get('note')||'').trim();if(!reason)throw Error('Chọn lý do loại.');return extra?reason+' '+extra:reason;}
function bulkBar(){return data.items.some(c=>c.status==='PENDING')?`<form id="change-bulk-reject" class="change-bulk"><span>Loại hàng loạt: tick các đề xuất bên dưới, chọn lý do rồi bấm loại.</span>${reasonSelect()}<button class="secondary-button" ${busy?'disabled':''}>Loại các mục đã chọn</button></form>`:'';}
function impactBox(c){const m=c.suggestion?.matches||[];return m.length?`<div class="info-callout change-impact"><strong>Nghĩa vụ có thể bị ảnh hưởng</strong><p class="field-hint">Gợi ý từ số hiệu văn bản trong đề xuất, cần kiểm tra lại.</p><ul>${m.map(x=>`<li>${esc(x.title)} · căn cứ ${esc(x.documentNumbers.join(', '))}</li>`).join('')}</ul></div>`:'<p class="field-hint">Không có nghĩa vụ đã phát hành nào trích dẫn văn bản được nhắc tới trong đề xuất.</p>';}
function workflowBox(c){
 if(c.stage==='NEEDS_IMPORT')return `<div class="info-callout"><strong>Đã đánh dấu: cần nhập văn bản vào kho để soạn nghĩa vụ mới</strong>${c.workflowJson?.note?`<p>${esc(c.workflowJson.note)}</p>`:''}${btn('Đưa về chờ phân loại','change-route-new')}</div>`;
 const w=c.workflow;if(!w)return '';
 return `<div class="info-callout"><strong>${w.ready?'Các nghĩa vụ đã được phát hành lại: có thể gửi cảnh báo':'Đang sửa nghĩa vụ'}</strong><ul>${w.items.map(i=>`<li>${esc(i.title)} · ${i.ready?'đã phát hành':esc(draftStatusText[i.draftStatus]||'chưa có bản nháp')}</li>`).join('')}</ul>${w.note?`<p>${esc(w.note)}</p>`:''}${w.ready?'':`<p>Sửa và duyệt các bản nháp trong Duyệt nghĩa vụ, rồi phát hành bộ checklist. Đề xuất này sẽ tự chuyển sang sẵn sàng gửi cảnh báo.</p><button type="button" class="primary-button" data-nav="admin">Sang Duyệt nghĩa vụ</button> ${btn('Hủy, đưa về chờ phân loại','change-route-new')}`}</div>`;
}
function renderDecision(c){
 const s=c.suggestion||{},pick=changeDecision,noRelease=!data.releases.length;
 const cards=`<div class="change-decisions" role="group" aria-label="Quyết định cho đề xuất">${DECISIONS.filter(([id])=>!noRelease||!['notify','update'].includes(id)).map(([id,label,hint])=>`<button type="button" class="change-decision ${pick===id?'selected':''}" data-alert-action="change-decision" data-id="${id}" aria-pressed="${pick===id}"><strong>${label}</strong><span>${hint}</span></button>`).join('')}</div>`;
 let form='';
 if(pick==='notify'&&!noRelease)form=`<form id="change-approve" class="product-form"><h3>Gửi cảnh báo cho doanh nghiệp</h3><p class="field-hint">Các ô đã được điền sẵn từ số hiệu và metadata văn bản. Sửa lại theo nội dung bản gốc trước khi duyệt.</p>${releaseChecks(s.versionIds||[])}${field('effectiveDate','Ngày áp dụng để đánh giá','date',s.effectiveDate||'')}${area('whatChanged','Thay đổi điều gì',s.whatChanged||'')}${area('why','Vì sao doanh nghiệp cần chú ý',s.why||'')}${area('action','Doanh nghiệp cần làm gì',s.action||'')}${area('note','Ghi nhận kết quả xác minh nguồn')}<details class="reviewer-aux"><summary>Xem trước cảnh báo doanh nghiệp sẽ nhận</summary><div data-alert-preview><p>${esc(s.whatChanged||'')}</p><p>${esc(s.why||'')}</p><p>${esc(s.action||'')}</p></div></details><label class="compliance-check"><input name="sourceVerified" type="checkbox" required> Tôi đã đối chiếu nguồn, hiệu lực và căn cứ của các nghĩa vụ được chọn.</label><button class="primary-button" ${busy||c.kind==='PARSER_CHANGE'?'disabled':''}>Duyệt và gửi cảnh báo</button></form>`;
 else if(pick==='update'&&!noRelease)form=`<form id="change-route-update" class="product-form"><h3>Chọn nghĩa vụ cần sửa</h3><p class="field-hint">Hệ thống tạo bản nháp mới (giữ nguyên nội dung hiện tại) để sửa trong Duyệt nghĩa vụ. Nghĩa vụ đang có bản nháp mở sẽ dùng lại bản đó.</p>${releaseChecks(s.versionIds||[])}<label>Ghi chú cần sửa gì (không bắt buộc)<textarea name="note" rows="3" maxlength="2000"></textarea></label><button class="primary-button" ${busy?'disabled':''}>Tạo bản nháp để sửa nghĩa vụ</button></form>`;
 else if(pick==='new')form=`<form id="change-route-import" class="product-form"><h3>Nghĩa vụ mới từ văn bản này</h3><p class="field-hint">Văn bản chưa có trong kho luật nên chưa trích dẫn được. Đánh dấu để nhập văn bản vào kho, sau đó soạn nghĩa vụ trong Duyệt nghĩa vụ.</p><label>Ghi chú nghĩa vụ dự kiến (không bắt buộc)<textarea name="note" rows="3" maxlength="2000"></textarea></label><button class="primary-button" ${busy?'disabled':''}>Đánh dấu cần nhập văn bản</button></form>`;
 else if(pick==='reject')form=`<form id="change-reject" class="product-form"><h3>Không liên quan</h3>${reasonSelect()}<label>Ghi chú thêm (không bắt buộc)<textarea name="note" rows="2" maxlength="1500"></textarea></label><button class="secondary-button" ${busy?'disabled':''}>Loại đề xuất</button></form>`;
 // Without a published catalogue no company can be targeted: say so up front and offer only the decisions that still work.
 return (noRelease?`<div class="info-callout" id="change-release-empty"><h3>Chưa có bộ checklist được phát hành</h3><p>Cần có ít nhất một checklist đã được duyệt để xác định doanh nghiệp nhận cảnh báo.</p><p>Vào Duyệt nghĩa vụ và duyệt checklist liên quan, sau đó quay lại đây.</p><button type="button" class="primary-button" data-nav="admin">Sang Duyệt nghĩa vụ</button></div>`:'')+impactBox(c)+workflowBox(c)+'<h3 class="change-decision-title">Quyết định</h3>'+cards+form;
}
function renderChange(c){const old=c.previous?.extractedJson,now=c.observation?.extractedJson;return `<h2>${esc(c.title)}</h2><p>${labels[c.kind]||esc(c.kind)} · ${labels[c.status]}</p>${collectionTime(c)}${c.diffJson.sourceUrl?`<a target="_blank" rel="noopener" href="${esc(c.diffJson.sourceUrl)}">Kiểm tra nguồn chính thức</a>`:''}<details><summary>Thông tin đối chiếu</summary><pre class="watch-diff">${esc(JSON.stringify(c.diffJson,null,2))}</pre></details>${old?`<details><summary>Toàn văn quan sát trước</summary><p class="field-hint">Thu thập lúc: ${esc(date(c.previous.observedAt))} (giờ Việt Nam)</p><p class="compliance-quote">${esc(old.fullText||'Nguồn chỉ có metadata; cần kiểm tra file gốc.')}</p></details>`:''}${now?`<details><summary>Toàn văn quan sát mới</summary><p class="compliance-quote">${esc(now.fullText||'Nguồn chỉ có metadata; cần kiểm tra file gốc.')}</p></details>`:''}${c.status==='PENDING'?renderDecision(c):`<p>Kết quả duyệt: ${esc(c.reviewNote)} · ${date(c.reviewedAt)}</p>${c.event?`<p>Ngày áp dụng ${esc(c.event.effectiveDate.slice(0,10))} · bộ checklist ${esc(c.event.releaseId)}</p>`:''}`}`;}
document.addEventListener('click',event=>{const b=event.target.closest('[data-alert-action]');if(!b||!h)return;if(b.dataset.alertAction==='expand'){const id=b.dataset.id;expanded.has(id)?expanded.delete(id):expanded.add(id);h.render();return;}if(b.dataset.alertAction==='change-decision'){changeDecision=b.dataset.id;h.render();return;}if(b.dataset.alertAction==='snooze'&&!data?.items.find(x=>x.id===b.dataset.id)?.userState?.snoozedUntil){pendingSnooze=b.dataset.id;h.render();return;}void run(async()=>{const id=b.dataset.id,a=data?.items.find(x=>x.id===id);switch(b.dataset.alertAction){case 'change-status':changeStatus=id;page=0;detail=null;await refresh();break;case 'change-view':changeView=id;detail=null;break;case 'change-page':{const target=Number(id),pages=Math.max(1,Math.ceil(data.total/CHANGE_PAGE_SIZE));if(!Number.isInteger(target)||target<0||target>=pages)break;page=target;detail=null;await refresh();break;}case 'watch-previous':watchPage--;await refresh();break;case 'watch-next':watchPage++;await refresh();break;case 'refresh':await refresh();break;case 'back':detail=null;break;case 'filter':filter=filter==='active'?'all':'active';break;case 'previous':page--;detail=null;await refresh();break;case 'next':page++;detail=null;await refresh();break;case 'change':detail=await h.api('/admin/changes/'+id);changeDecision=detail.workflow?.ready?'notify':null;break;case 'change-route-new':await h.api('/admin/changes/'+detail.id+'/route','POST',{expectedRevision:detail.revision,stage:'NEW'});detail=await h.api('/admin/changes/'+detail.id);changeDecision=null;await refresh();break;case 'read':await h.api('/alerts/'+id,'PATCH',{read:!a.userState?.readAt});await refresh();break;case 'snooze':await h.api('/alerts/'+id,'PATCH',{snoozedUntil:a.userState?.snoozedUntil?null:null});await refresh();break;case 'task':{const task=await h.api('/alerts/'+id+'/task','POST',{});h.openTask(task.id);break;}case 'impact-retry':await h.api('/admin/change-impacts/'+id+'/retry','POST',{});await refresh();break;case 'recheck':await h.api('/admin/watchset/'+id,'PATCH',{recheck:true});await refresh();break;case 'watch-toggle':{const w=data.watch.items.find(x=>x.id===id);await h.api('/admin/watchset/'+id,'PATCH',{enabled:!w.enabled});await refresh();break;}}}).then(()=>{if(b.dataset.alertAction==='change-page'&&!error)document.querySelector('.change-list-heading')?.scrollIntoView({block:'start'});});});
document.addEventListener('submit',event=>{const form=event.target;if(!['alert-settings','change-manual','change-approve','change-reject','watch-add','change-route-update','change-route-import','change-bulk-reject'].includes(form.id))return;event.preventDefault();const f=new FormData(form);void run(async()=>{switch(form.id){case 'alert-settings':await h.api('/companies/'+h.company().id+'/reminders','PUT',{enabled:f.has('enabled'),preparationDays:Number(f.get('preparationDays'))});break;case 'change-manual':checkText(f,'title','Tên thay đổi');checkText(f,'note','Nội dung cần xác minh');await h.api('/admin/changes','POST',Object.fromEntries(f));changeView='list';changeStatus='all';page=0;break;case 'watch-add':await h.api('/admin/watchset','POST',{url:f.get('url'),mode:f.get('mode')});break;case 'change-reject':await h.api('/admin/changes/'+detail.id+'/reject','POST',{expectedRevision:detail.revision,note:rejectNote(f)});detail=null;break;
case 'change-route-update':{const ids=f.getAll('versionIds');if(!ids.length)throw Error('Chọn ít nhất một nghĩa vụ cần sửa.');await h.api('/admin/changes/'+detail.id+'/route','POST',{expectedRevision:detail.revision,stage:'OBLIGATION_UPDATE',versionIds:ids,note:String(f.get('note')||'')});detail=await h.api('/admin/changes/'+detail.id);changeDecision=null;notify(`Đã tạo bản nháp cho ${ids.length} nghĩa vụ. Sửa và phát hành trong Duyệt nghĩa vụ, sau đó quay lại gửi cảnh báo.`);break;}
case 'change-route-import':await h.api('/admin/changes/'+detail.id+'/route','POST',{expectedRevision:detail.revision,stage:'NEEDS_IMPORT',note:String(f.get('note')||'')});detail=await h.api('/admin/changes/'+detail.id);changeDecision=null;notify('Đã đánh dấu: cần nhập văn bản vào kho để soạn nghĩa vụ mới.');break;
case 'change-bulk-reject':{const ids=f.getAll('bulk'),note=rejectNote(f);if(!ids.length)throw Error('Tick ít nhất một đề xuất để loại.');let done=0;const failed=[];for(const cid of ids){const item=data.items.find(x=>x.id===cid);try{await h.api('/admin/changes/'+cid+'/reject','POST',{expectedRevision:item.revision,note});done++;}catch{failed.push(cid);}}if(done)notify(`Đã loại ${done} đề xuất.`);if(failed.length)throw Error(`${failed.length} đề xuất chưa loại được (có thể đã được người khác xử lý). Tải lại để xem.`);break;}case 'change-approve':{const release=data.releases[0],selected=f.getAll('versionIds');if(!release)throw Error('Chọn bộ checklist đã phát hành.');if(!selected.length)throw Error('Chọn ít nhất một checklist liên quan trong bộ đã phát hành.');if(selected.some(id=>!release.items.some(item=>item.versionId===id)))throw Error('Chỉ chọn checklist trong bộ đã phát hành đang dùng.');for(const [name,label] of Object.entries({whatChanged:'Thay đổi điều gì',why:'Vì sao doanh nghiệp cần chú ý',action:'Doanh nghiệp cần làm gì',note:'Ghi nhận kết quả xác minh nguồn'}))checkText(f,name,label);await h.api('/admin/changes/'+detail.id+'/approve','POST',{expectedRevision:detail.revision,effectiveDate:f.get('effectiveDate'),versionIds:selected,whatChanged:f.get('whatChanged'),why:f.get('why'),action:f.get('action'),note:f.get('note'),sourceVerified:f.has('sourceVerified')});detail=null;break;}}await refresh();});});

export function renderAlertOverlay(){if(!pendingSnooze||h?.screen()!=='alerts')return '';const a=data?.items.find(x=>x.id===pendingSnooze);if(!a)return '';const local=x=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(x),min=local(new Date(Date.now()+86400000)),max=local(new Date(Date.now()+90*86400000)),suggested=local(new Date(Date.now()+7*86400000));return `<div class="overlay-backdrop centered"><div class="reason-dialog" role="dialog" aria-modal="true" aria-labelledby="product-snooze-title"><button type="button" class="close-button" data-snooze-cancel aria-label="Đóng">${h.icon('close',20)}</button><div class="dialog-icon">${h.icon('calendar',22)}</div><h2 id="product-snooze-title">Khi nào LIMI nhắc lại?</h2><p>${esc(a.title)}</p><form id="alert-snooze"><label for="product-snooze-date">Ngày hiển thị lại cảnh báo</label><input id="product-snooze-date" name="until" type="date" min="${min}" max="${max}" value="${suggested}" required><p class="field-hint">Cảnh báo tạm ẩn đến ngày bạn chọn, trong 90 ngày tới. Ngày lưu theo giờ Việt Nam và tài khoản hiện tại.</p>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="dialog-actions"><button type="button" class="secondary-button" data-snooze-cancel>Hủy</button><button class="primary-button" ${busy?'disabled':''}>Lưu ngày nhắc</button></div></form></div></div>`;}
document.addEventListener('click',event=>{if(event.target.closest('[data-snooze-cancel]')){pendingSnooze=null;h.render();}if(event.target.closest('[data-nav]'))pendingSnooze=null;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&pendingSnooze){pendingSnooze=null;h.render();}});
document.addEventListener('submit',event=>{if(event.target.id!=='alert-snooze')return;event.preventDefault();const until=String(new FormData(event.target).get('until')||'');void run(async()=>{await h.api('/alerts/'+pendingSnooze,'PATCH',{snoozedUntil:new Date(until+'T00:00:00+07:00').toISOString()});pendingSnooze=null;await refresh();});});

document.addEventListener('change',event=>{if(event.target.id!=='change-status'||!h)return;const selected=event.target.value;void run(async()=>{changeStatus=selected;page=0;detail=null;await refresh();});});

document.addEventListener('input',e=>{const form=e.target.closest('#change-approve');if(!form)return;const preview=form.querySelector('[data-alert-preview]');if(!preview)return;const fd=new FormData(form);preview.innerHTML=['whatChanged','why','action'].map(k=>`<p>${esc(fd.get(k)||'')}</p>`).join('');});
